/* @lc app=leetcode id=2392 lang=kotlin */
class Solution { fun buildMatrix(k: Int, rowConditions: Array<IntArray>, colConditions: Array<IntArray>): Array<IntArray> = { topo: (Int, Array<IntArray>) -> List<Int>? -> topo(k, rowConditions)?.let { r -> topo(k, colConditions)?.let { c -> Array(k) { IntArray(k) }.apply { (1..k).all { i -> this[r.indexOf(i)][c.indexOf(i)] = i.let { true } } } } } ?: arrayOf<IntArray>() }({ n, conds -> IntArray(n + 1).let { indeg -> Array(n + 1) { mutableListOf<Int>() }.also { adj -> conds.all { c -> adj[c[0]].add(c[1]).also { indeg[c[1]]++ } } }.let { adj -> generateSequence(mutableListOf<Int>().apply { (1..n).all { if (indeg[it] == 0) add(it) else true } }) { q -> q.flatMap { u -> adj[u].filter { v -> --indeg[v] == 0 } }.toMutableList().takeIf { it.isNotEmpty() } }.flatMap { it.asSequence() }.toList().takeIf { it.size == n } } } }) }